contents.rollMessage:
%{
  const props = entity.system.props;
  const pool = Number(props.kraft ?? 0) + Number(props.wille ?? 0);
  if (pool <= 0) return `<strong>Mut</strong>: Pool 0, kein Wurf möglich.`;
  const roll = await new Roll(pool + "d6").evaluate();
  const faces = roll.terms.at(0).results.map(r => r.result).sort((a,b) => a-b);
  const sechser = faces.filter(f => f === 6).length;
  const einser = faces.filter(f => f === 1).length;
  let text = `<strong>Mut</strong> (Pool ${pool}): (${faces.join(', ')})<br>Erfolge (6er): <strong>${sechser}</strong> &nbsp; Einser: <strong>${einser}</strong>`;
  if (einser >= 3) text += `<br>⚠️ Kritischer Misserfolg (3+ Einser)`;
  if (sechser >= 3) text += `<br>✨ Kritischer Erfolg (3+ Sechser)`;
  return text;
}%

